export const main="<section class=\"sw-hero\" aria-labelledby=\"sw-title\">\n  <img class=\"sw-hero-photo\" src=\"/shift-for-work/assets/hero.webp\" width=\"1536\" height=\"1024\" alt=\"Three men sharing a relaxed conversation during a workplace break\" fetchpriority=\"high\">\n  <div class=\"sw-hero-shade\" aria-hidden=\"true\"></div>\n  <div class=\"sw-wrap sw-hero-copy\"><p class=\"sw-kicker\">SHIFT for Work</p><h1 id=\"sw-title\">Better support.<br>For the people<br><span>behind the job.</span></h1><p class=\"sw-deck\">Practical help with weight, food, movement and everyday wellbeing, built around working life.</p><div class=\"sw-actions\"><a class=\"sw-button\" href=\"#work-enquiry\">Talk about your workforce <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a><a class=\"sw-button sw-outline\" href=\"/join-my-timber\">Explore free My Timber <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a></div></div>\n</section>\n<section class=\"sw-free\" aria-labelledby=\"sw-free-title\"><div class=\"sw-wrap sw-free-grid\"><div class=\"sw-free-copy\"><h2 id=\"sw-free-title\">A useful place for<br>your people to start.</h2><p>My Timber is free for individuals, with practical tools for food, movement, check-ins and progress.</p><a class=\"sw-button\" href=\"/join-my-timber\">Explore My Timber <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a></div><img src=\"/shift-for-work/assets/lunch.webp\" width=\"1536\" height=\"1024\" alt=\"A man enjoying his packed lunch in a workplace break room\" loading=\"lazy\"></div></section>\n<section class=\"sw-support\" aria-labelledby=\"sw-support-title\"><div class=\"sw-wrap\"><h2 id=\"sw-support-title\">Support that fits real life.</h2><div class=\"sw-cards\">\n<a class=\"sw-card\" href=\"/the-programme\"><svg class=\"sw-card-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M8 5v14c0 5 10 5 10 0V5M13 5v34m17 0V5c-8 4-10 17 0 19\"/></svg><h3>Food &amp; movement</h3><p>Ideas that fit a busy week.</p><span class=\"sw-card-link\">Explore the Programme <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></span></a>\n<a class=\"sw-card\" href=\"/shift-health\"><svg class=\"sw-card-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M24 41S4 29 4 16C4 4 18 2 24 12 30 2 44 4 44 16c0 13-20 25-20 25Z\"/><path d=\"M9 24h9l4-8 5 15 4-7h8\"/></svg><h3>Weight &amp; wider health</h3><p>Clear information and routes to assessment.</p><span class=\"sw-card-link\">Explore SHIFT Health <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></span></a>\n<a class=\"sw-card\" href=\"/mens-mental-health\"><svg class=\"sw-card-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M10 35 5 43l13-4c22 7 34-11 24-25C28-6 1 3 4 23c1 5 3 9 6 12Z\"/></svg><h3>Good to Talk</h3><p>Free guides for everyday pressures.</p><span class=\"sw-card-link\">Explore Good to Talk <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></span></a>\n</div></div></section>\n<section class=\"sw-privacy\" aria-labelledby=\"sw-privacy-title\"><div class=\"sw-wrap sw-privacy-grid\"><div><h2 id=\"sw-privacy-title\">Personal support.<br>Private accounts.</h2><p>Give your team a useful starting point. Keep personal goals, health details and staff records out of an employer enquiry.</p></div><aside class=\"sw-business\"><svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><rect x=\"10\" y=\"20\" width=\"28\" height=\"24\" rx=\"3\"/><path d=\"M16 20V11a8 8 0 0 1 16 0v9m-8 10v5\"/></svg><div><h3>Start with your business needs</h3><ul><li>Type of work</li><li>Size of team</li><li>What would be useful</li></ul></div></aside></div></section>\n<section class=\"sw-steps\" aria-label=\"How an employer enquiry works\"><ol class=\"sw-wrap\"><li><span class=\"sw-number\">01</span><div><h3>Tell us about your team.</h3><p>Share a few details about your organisation and what you’re looking to support.</p></div></li><li><span class=\"sw-number\">02</span><div><h3>Discuss the right scope.</h3><p>We’ll explore what could work for your people and answer your questions.</p></div></li><li><span class=\"sw-number\">03</span><div><h3>Agree the detail together.</h3><p>We’ll confirm the best next steps based on your needs.</p></div></li></ol></section>\n<section class=\"sw-enquiry\" id=\"work-enquiry\" aria-labelledby=\"sw-enquiry-title\"><div class=\"sw-wrap sw-enquiry-grid\"><div class=\"sw-enquiry-copy\"><h2 id=\"sw-enquiry-title\">Could this work<br>for your people?</h2><p>Tell us about your organisation and what you’d like to support. We’ll discuss what makes sense for your team.</p><p class=\"sw-small\">Prefer email? <a href=\"mailto:partners@shiftsometimber.co.uk\">partners@shiftsometimber.co.uk</a></p></div>\n<form id=\"shift-work-enquiry\" action=\"/v1/contact\" method=\"post\" data-work-enquiry aria-describedby=\"enquiry-privacy\"><div class=\"sw-fields\">\n<label for=\"work-name\">Your name<input id=\"work-name\" name=\"name\" autocomplete=\"name\" maxlength=\"100\" placeholder=\"Full name\" required></label>\n<label for=\"work-email\">Work email<input id=\"work-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"name@organisation.co.uk\" required></label>\n<label for=\"work-company\">Organisation<input id=\"work-company\" name=\"company\" autocomplete=\"organization\" maxlength=\"160\" placeholder=\"Your organisation\" required></label>\n<label for=\"work-sector\">Sector<select id=\"work-sector\" name=\"sector\" required><option value=\"\">Select a sector</option><option>Haulage and logistics</option><option>Construction and trades</option><option>Manufacturing and warehousing</option><option>Grounds care and landscaping</option><option>Security</option><option>Football and sport</option><option>Other</option></select></label>\n<label for=\"work-size\">Team size<select id=\"work-size\" name=\"workforce\" required><option value=\"\">Select team size</option><option>Under 30</option><option>30–75</option><option>76–250</option><option>251–499</option><option>500+</option></select></label>\n<label for=\"work-role\">Your role <span>(optional)</span><input id=\"work-role\" name=\"role\" autocomplete=\"organization-title\" maxlength=\"100\" placeholder=\"Your role\"></label>\n</div><label class=\"sw-consent\" for=\"work-consent\"><input id=\"work-consent\" name=\"consent\" type=\"checkbox\" required><span>SHIFT may use these business contact details to respond to my enquiry.</span></label>\n<button class=\"sw-button\" type=\"submit\" disabled>Start the conversation <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></button><p id=\"enquiry-privacy\" class=\"sw-small\">Business contact details only. Please don’t include employee health information. SHIFT will use your details to respond, with a copy sent to your email and the partnerships inbox. This does not subscribe you to marketing or register any employee. Read our <a href=\"/privacy\">privacy notice</a>.</p>\n<noscript><p>Email <a href=\"mailto:partners@shiftsometimber.co.uk\">partners@shiftsometimber.co.uk</a> to start the conversation. Please don’t include employee health information.</p></noscript><p id=\"work-form-status\" class=\"sw-status\" role=\"status\" aria-live=\"polite\" tabindex=\"-1\"></p></form></div></section>\n";
